def maximumTime(s: str) -> str:
    # Convert string to list for easier modification
    time_list = list(s)

    # Handle hour part (positions 0 and 1)
    if time_list[0] == '?' and time_list[1] == '?':
        # Maximum hour is 11
        time_list[0] = '1'
        time_list[1] = '1'
    elif time_list[0] == '?':
        # Determine first digit of hour based on second digit
        if time_list[1] <= '1':
            time_list[0] = '1'
        else:
            time_list[0] = '0'
    elif time_list[1] == '?':
        # Determine second digit of hour based on first digit
        if time_list[0] == '0':
            time_list[1] = '9'
        else:  # time_list[0] == '1'
            time_list[1] = '1'

    # Handle minute part (positions 3 and 4)
    if time_list[3] == '?' and time_list[4] == '?':
        # Maximum minute is 59
        time_list[3] = '5'
        time_list[4] = '9'
    elif time_list[3] == '?':
        time_list[3] = '5'
    elif time_list[4] == '?':
        time_list[4] = '9'

    return ''.join(time_list)
