class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n+1))
        self.rank = [0] * (n+1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False
        if self.rank[px] < self.rank[py]:
            self.parent[px] = py
        elif self.rank[px] > self.rank[py]:
            self.parent[py] = px
        else:
            self.parent[py] = px
            self.rank[px] += 1
        return True

def main():
    data = input().split()
    idx = 0
    N = int(data[idx])
    idx += 1
    M = int(data[idx])
    idx += 1
    ops = []
    for _ in range(M):
        K = int(data[idx])
        idx += 1
        C = int(data[idx])
        idx += 1
        A = [int(data[idx + j]) for j in range(K)]
        idx += K
        ops.append((C, A))
    ops.sort()
    uf = UnionFind(N)
    total = 0
    for C, A in ops:
        if not A:
            continue
        roots = set()
        for v in A:
            roots.add(uf.find(v))
        roots = list(roots)
        if len(roots) > 1:
            for i in range(1, len(roots)):
                if uf.union(roots[0], roots[i]):
                    total += C
    comp = uf.find(1)
    connected = True
    for i in range(2, N+1):
        if uf.find(i) != comp:
            connected = False
            break
    if connected:
        print(total)
    else:
        print(-1)

