  INF = 10**30
  adj = [[] for _ in range(N)]
  idx = 2
  for _ in range(M):
    u = int(data[idx]) - 1
    v = int(data[idx + 1]) - 1
    w = int(data[idx + 2])
    adj[u].append((v, w))
    idx += 3
  dp = [[INF] * N for _ in range(1 << N)]
  for i in range(N):
    dp[1 << i][i] = 0
  for mask in range(1 << N):
    nodes_in = [j for j in range(N) if (mask & (1 << j))]
    S = len(nodes_in)
    for _ in range(S):
      updated = False
      for u in nodes_in:
        if dp[mask][u] == INF:
          continue
        for v, w in adj[u]:
          if (mask & (1 << v)) != 0:
            if dp[mask][v] > dp[mask][u] + w:
              dp[mask][v] = dp[mask][u] + w
              updated = True
      if not updated:
        break
    for u in nodes_in:
