def max_energy(energy, k):
    n = len(energy)
    if n == 0:
        return 0

    # dp[i] represents the maximum energy we can gain starting from position i
    dp = [0] * n

    # Process from the end backwards
    for i in range(n - 1, -1, -1):
        # If we can jump to another position (i + k < n)
        if i + k < n:
            dp[i] = energy[i] + dp[i + k]
        else:
            # If jump goes beyond array, we just take energy[i]
            dp[i] = energy[i]

    # Return the maximum value in dp array
    return max(dp)
