        adj[u].append(v)
        adj[v].append(u)
        deg[u] += 1
        deg[v] += 1
    centers = set()
    for v in range(1, N+1):
        if deg[v] >= 3:
            centers.add(v)
    for v in range(1, N+1):
        if deg[v] == 1:
            nei = adj[v][0]
            centers.add(nei)
    # propagate using bridges
    changed = True
    while changed:
        changed = False
        new_centers = set()
        for c in centers:
            for nei in adj[c]:
                if deg[nei] == 2:
                    # find the pair
                    for nn in adj[nei]:
                        if nn != c:
                            pair = nn
                            break
                    if deg[pair] == 2:
                        for other in adj[pair]:
                            if other != nei:
                                if other not in centers:
                                    new_centers.add(other)
                                    changed = True
        centers.update(new_centers)
    levels = [deg[c] for c in centers]
