    row_freq = [[0] * 26 for _ in range(H)]
    col_freq = [[0] * 26 for _ in range(W)]
    total_row = [0] * H
    total_col = [0] * W
    for i in range(H):
        for j in range(W):
            c = ord(grid[i][j]) - 97
            row_freq[i][c] += 1
            col_freq[j][c] += 1
            total_row[i] += 1
            total_col[j] += 1
    while True:
        marked_rows = []
        for i in range(H):
            if total_row[i] >= 2:
                colors = 0
                for k in range(26):
                    if row_freq[i][k] > 0:
                        colors += 1
                if colors == 1:
                    marked_rows.append(i)
        marked_cols = []
        for j in range(W):
            if total_col[j] >= 2:
                colors = 0
                for k in range(26):
                    if col_freq[j][k] > 0:
                        colors += 1
