def maximum_length(s: str) -> int:
    n = len(s)
    # For each character, record lengths of consecutive runs
    runs = {chr(c): [] for c in range(ord('a'), ord('z') + 1)}

    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        length = j - i
        runs[s[i]].append(length)
        i = j

    max_len = -1

    # For each character, find the longest special substring that appears at least 3 times
    for char, lengths in runs.items():
        if not lengths:
            continue

        # We need to check substrings of length L (from 1 to max length for this char)
        # For a run of length 'l', it contains (l - L + 1) substrings of length L (if l >= L)
        # But for multiple runs, we need to sum over all runs
        max_run = max(lengths)

        # Try possible L values from 1 to max_run
        for L in range(1, max_run + 1):
            count = 0
            for l in lengths:
                if l >= L:
                    count += (l - L + 1)

            if count >= 3:
                max_len = max(max_len, L)

    return max_len
