def main():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    X = [int(data[i]) for i in range(1, 2*N+1, 2)]
    Y = [int(data[i]) for i in range(2, 2*N+1, 2)]
    MAXC = 40
    INF = float('inf')
    dp = [[INF] * (MAXC + 1) for _ in range(N)]
    dp[0][0] = 0.0
    for i in range(1, N):
        for c in range(MAXC + 1):
            for k in range(min(c, i) + 1):
                j = i - k - 1
                if j < 0:
                    continue
                prev_c = c - k
                if prev_c > MAXC or dp[j][prev_c] == INF:
                    continue
                dist = math.hypot(X[i] - X[j], Y[i] - Y[j])
                if dp[j][prev_c] + dist < dp[i][c]:
                    dp[i][c] = dp[j][prev_c] + dist
    ans = INF
    # C=0
    if dp[N-1][0] < INF:
        ans = dp[N-1][0]
    for c in range(1, MAXC + 1):
        if dp[N-1][c] < INF:
            penalty = 1 << (c - 1)  # 2^{c-1}
            ans = min(ans, dp[N-1][c] + penalty)
    print(ans)

