def count_sub_multisets(nums, l, r):
    MOD = 10**9 + 7
    freq = {}
    for x in nums:
        freq[x] = freq.get(x, 0) + 1

    dp = [0] * (r + 1)
    dp[0] = 1

    for num, count in freq.items():
        new_dp = dp[:]
        for s in range(r + 1):
            if dp[s] == 0:
                continue
            for k in range(1, count + 1):
                ns = s + num * k
                if ns > r:
                    break
                new_dp[ns] = (new_dp[ns] + dp[s]) % MOD
        dp = new_dp

    return sum(dp[l:r+1]) % MOD
