def min_length_t(s: str) -> int:
    n = len(s)

    # Try all possible lengths of t that divide n
    for length in range(1, n + 1):
        if n % length != 0:
            continue

        # Count frequency of characters in s
        total_freq = {}
        for char in s:
            total_freq[char] = total_freq.get(char, 0) + 1

        # Check if t of given length is possible
        # Each character must appear (total_freq[char] // (n // length)) * (n // length) times in total
        # i.e., total_freq[char] must be divisible by (n // length)
        num_anagrams = n // length
        possible = True

        for count in total_freq.values():
            if count % num_anagrams != 0:
                possible = False
                break

        if possible:
            return length

    return n
