def max_gold(n, offers):
    offers.sort(key=lambda x: x[1])
    dp = [0] * (n + 1)

    for start, end, gold in offers:
        # Binary search for the latest non-overlapping offer
        left, right = 0, len(offers) - 1
        best_idx = -1
        while left <= right:
            mid = (left + right) // 2
            if offers[mid][1] < start:
                best_idx = mid
                left = mid + 1
            else:
                right = mid - 1

        prev_dp = dp[best_idx + 1] if best_idx != -1 else dp[0]
        dp[end + 1] = max(dp[end + 1], prev_dp + gold)

    return max(dp)
