def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    M = int(data[1])
    edges = []
    index = 2
    for _ in range(M):
        A = int(data[index])
        B = int(data[index + 1])
        edges.append((A, B))
        index += 2
    # Build graph: edge u -> v means u stronger than v
    graph = [[False] * (N + 1) for _ in range(N + 1)]
    for u in range(1, N + 1):
        graph[u][u] = True
    for A, B in edges:
        graph[A][B] = True
    # Floyd-Warshall for transitive closure
    for k in range(1, N + 1):
        for i in range(1, N + 1):
            for j in range(1, N + 1):
                if graph[i][k] and graph[k][j]:
                    graph[i][j] = True
    # Find nodes with no incoming edges from others
    candidates = []
    for i in range(1, N + 1):
        has_incoming = False
        for j in range(1, N + 1):
            if j != i and graph[j][i]:
                has_incoming = True
