def min_operations_to_median(nums, k):
    nums.sort()
    n = len(nums)
    median_index = (n - 1) // 2 if n % 2 == 1 else n // 2
    operations = 0

    for i in range(n):
        if i <= median_index:
            if nums[i] > k:
                operations += nums[i] - k
                nums[i] = k
        else:
            if nums[i] < k:
                operations += k - nums[i]
                nums[i] = k

    return abs(nums[median_index] - k) + operations
