def countStableArrays(zero: int, one: int, limit: int) -> int:
    MOD = 10**9 + 7
    dp = {}

    def dfs(remain_zero, remain_one, last_run_val, last_run_len):
        key = (remain_zero, remain_one, last_run_val, last_run_len)
        if key in dp:
            return dp[key]

        if remain_zero == 0 and remain_one == 0:
            return 1

        total = 0

        # Try adding 0
        if remain_zero > 0:
            if last_run_val == 0 and last_run_len < limit:
                total += dfs(remain_zero - 1, remain_one, 0, last_run_len + 1)
            elif last_run_val != 0:
                total += dfs(remain_zero - 1, remain_one, 0, 1)

        # Try adding 1
        if remain_one > 0:
            if last_run_val == 1 and last_run_len < limit:
                total += dfs(remain_zero, remain_one - 1, 1, last_run_len + 1)
            elif last_run_val != 1:
                total += dfs(remain_zero, remain_one - 1, 1, 1)

        dp[key] = total % MOD
        return dp[key]

    return dfs(zero, one, -1, 0)
