def maxSumOfSquares(nums, k):
    MOD = 10**9 + 7
    n = len(nums)

    # Count set bits across all numbers for each bit position
    bit_count = [0] * 32
    for num in nums:
        for i in range(32):
            if num & (1 << i):
                bit_count[i] += 1

    # Reconstruct the array optimally: maximize individual numbers
    new_nums = []
    # Create as many large numbers as possible by maximizing higher bits first
    for _ in range(n):
        num = 0
        for i in range(31, -1, -1):
            if bit_count[i] > 0:
                num |= (1 << i)
                bit_count[i] -= 1
        new_nums.append(num)

    # Take the largest k numbers (already sorted in descending order by construction)
    result = 0
    for i in range(k):
        result = (result + new_nums[i] * new_nums[i]) % MOD

    return result
