def maxNumber(k, x):
    def price_sum(num):
        if num <= 0:
            return 0
        total = 0
        pos = 1
        while (1 << (pos - 1)) <= num:
            if pos % x == 0:
                full_cycles = num // (1 << pos)
                remainder = num % (1 << pos)
                ones_in_full = full_cycles * (1 << (pos - 1))
                ones_in_partial = max(0, remainder - (1 << (pos - 1)))
                total += ones_in_full + ones_in_partial
            pos += 1
        return total

    low, high = 1, 10**15
    while low < high:
        mid = (low + high + 1) // 2
        if price_sum(mid) <= k:
            low = mid
        else:
            high = mid - 1
