import sys

def count_nodes(A, D, N):
    if D > 60:
        return 0
    L = A << D
    if L > N:
        return 0
    R = L + (1 << D) - 1
    return max(0, min(N, R) - L + 1)

def solve(N, X, K):
    if K == 0:
        return 1
    ans = 0
    DX = 0
    tmp = X
    while tmp > 1:
        tmp >>= 1
        DX += 1
    for U in range(0, min(K, DX) + 1):
        D = K - U
        if D < 0:
            continue
        A = X >> U
        if U == 0:
            ans += count_nodes(A, D, N)
        else:
            if D == 0:
                ans += 1
            else:
                C = X >> (U - 1)
                total = count_nodes(A, D, N)
                sub = count_nodes(C, D - 1, N)
                ans += total - sub
    return ans

def main():
