import sys
import itertools

def solve():
    input = sys.stdin.read
    data = input().split()
    index = 0
    N = int(data[index])
    index += 1
    H = int(data[index])
    index += 1
    W = int(data[index])
    index += 1
    tiles = []
    for i in range(N):
        A = int(data[index])
        index += 1
        B = int(data[index])
        index += 1
        tiles.append((A, B))

    total_area = H * W
    possible = False

    for mask in range(1 << N):
        selected = []
        area = 0
        for i in range(N):
            if mask & (1 << i):
                selected.append(tiles[i])
                area += tiles[i][0] * tiles[i][1]
        if area != total_area:
            continue
        K = len(selected)
        for orient_mask in range(1 << K):
            oriented = []
            for j in range(K):
                a, b = selected[j]
                if orient_mask & (1 << j):
                    oriented.append((b, a))
                else:
                    oriented.append((a, b))
            # now check if can tile with oriented
            if can_tile(H, W, oriented):
                possible = True
                break
        if possible:
            break

    print("Yes" if possible else "No")

def can_tile(H, W, rects):
    K = len(rects)
    if K == 0:
        return H == 0 and W == 0
    grid = [[False for _ in range(W)] for _ in range(H)]

    def find_next_empty():
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    return i, j
        return None

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(h):
            for j in range(w):
                if grid[r + i][c + j]:
                    return False
        return True

    def do_place(r, c, h, w, val):
        for i in range(h):
            for j in range(w):
                grid[r + i][c + j] = val

    def bt(used_count):
        pos = find_next_empty()
        if pos is None:
            return True
        r, c = pos
        for idx in range(K):
            if used[idx]:
                continue
            h, w = rects[idx]
            # try this orientation
            if can_place(r, c, h, w):
                do_place(r, c, h, w, True)
                used[idx] = True
                if bt(used_count + 1):
                    return True
                used[idx] = False
                do_place(r, c, h, w, False)
            # try rotated if different
            if h != w:
                hr, wr = w, h
                if can_place(r, c, hr, wr):
                    do_place(r, c, hr, wr, True)
                    used[idx] = True
                    if bt(used_count + 1):
                        return True
                    used[idx] = False
                    do_place(r, c, hr, wr, False)
        return False

    used = [False] * K
    return bt(0)

solve()
