from collections import deque
def minOperations(x: int, y: int) -> int:
    if x == y:
        return 0
    MAX = max(x, y) + 1000
    queue = deque([(x, 0)])
    visited = set([x])
    while queue:
        curr, steps = queue.popleft()
        candidates = []
        if curr % 11 == 0:
            candidates.append(curr // 11)
        if curr % 5 == 0:
            candidates.append(curr // 5)
        candidates.append(curr + 1)
        candidates.append(curr - 1)
        for nxt in candidates:
            if nxt == y:
                return steps + 1
            if 0 < nxt <= MAX and nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, steps + 1))
    return -1
