def beautifulIndices(s: str, a: str, b: str, k: int) -> list[int]:
    # Find all indices where string a appears in s
    a_positions = []
    for i in range(len(s) - len(a) + 1):
        if s[i:i + len(a)] == a:
            a_positions.append(i)

    # Find all indices where string b appears in s
    b_positions = []
    for j in range(len(s) - len(b) + 1):
        if s[j:j + len(b)] == b:
            b_positions.append(j)

    # For each position in a_positions, check if there exists a position in b_positions
    # such that |j - i| <= k
    result = []
    for i in a_positions:
        # Binary search for the closest b position to i
        left, right = 0, len(b_positions) - 1
        closest_dist = float('inf')

        while left <= right:
            mid = (left + right) // 2
            dist = abs(b_positions[mid] - i)
            closest_dist = min(closest_dist, dist)

            if b_positions[mid] == i:
