def maximumPrimeDistance(nums):
    # Helper function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Find all indices where nums[i] is prime
    prime_indices = [i for i, num in enumerate(nums) if is_prime(num)]

    # Since the array contains at least one prime, we can safely compute max distance
    return prime_indices[-1] - prime_indices[0]
