def longestSubsequence(nums, target):
    n = len(nums)
    # dp[i][s] = max length of subsequence ending before index i with sum s
    dp = [[-1] * (target + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = 0

    for i in range(1, n + 1):
        num = nums[i-1]
        for s in range(target + 1):
            dp[i][s] = dp[i-1][s]
            if s >= num and dp[i-1][s-num] != -1:
                dp[i][s] = max(dp[i][s], dp[i-1][s-num] + 1)

    return dp[n][target]
