from collections import defaultdict

def main():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    index = 2
    edges = []

    for _ in range(m):
        k = int(data[index])
        c = int(data[index + 1])
        index += 2
        vertices = list(map(int, data[index:index + k]))
        index += k

        # Add all pairs (u, v) with u < v in this subset
        for i in range(k):
            for j in range(i + 1, k):
                u, v = vertices[i], vertices[j]
                edges.append((c, u, v))

    # Remove duplicate edges, keeping the one with minimum weight
    edge_dict = {}
    for c, u, v in edges:
        key = (min(u, v), max(u, v))
        if key not in edge_dict or edge_dict[key] > c:
            edge_dict[key] = c

    edges = [(c, u, v) for (u, v), c in edge_dict.items()]

    # Sort edges by weight for Kruskal's algorithm
    edges.sort()

    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    total_weight = 0
    edge_count = 0

    for c, u, v in edges:
        if union(u, v):
            total_weight += c
            edge_count += 1
            if edge_count == n - 1:
                break

    if edge_count == n - 1:
        print(total_weight)
    else:
        print(-1)

