import sys

def solve():
    data = sys.stdin.read().split()
    H = int(data[0])
    W = int(data[1])
    grid = data[2:]
    MOD = 998244353

    # Count red cells
    R = sum(row.count('.') for row in grid)

    # Union-Find structure for green cells
    parent = [-1] * (H * W)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    # Initialize green cells
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                idx = i * W + j
                parent[idx] = idx

    # Union adjacent green cells (right and down)
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                idx = i * W + j
                if j + 1 < W and grid[i][j + 1] == '#':
                    union(idx, idx + 1)
                if i + 1 < H and grid[i + 1][j] == '#':
                    union(idx, idx + W)

    # Count distinct green components
    roots = set()
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                roots.add(find(i * W + j))
    C = len(roots)

    # For each red cell, count distinct adjacent green components
    sum_c = 0
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                adj = set()
                if i > 0 and grid[i - 1][j] == '#':
                    adj.add(find((i - 1) * W + j))
                if i + 1 < H and grid[i + 1][j] == '#':
                    adj.add(find((i + 1) * W + j))
                if j > 0 and grid[i][j - 1] == '#':
                    adj.add(find(i * W + (j - 1)))
                if j + 1 < W and grid[i][j + 1] == '#':
                    adj.add(find(i * W + (j + 1)))
                sum_c += len(adj)

    # Expected value = ((C + 1) * R - sum_c) / R  (mod MOD)
    num = ((C + 1) * R - sum_c) % MOD
    inv_R = pow(R, MOD - 2, MOD)
    ans = (num * inv_R) % MOD
    print(ans)

