def countSubMultisets(nums, l, r):
    MOD = 10**9 + 7
    from collections import Counter

    cnt = Counter(nums)
    dp = [0] * (r + 1)
    dp[0] = 1

    for num, freq in cnt.items():
        if num == 0:
            dp[0] = (dp[0] * (freq + 1)) % MOD
            continue
        for s in range(r, -1, -1):
            if dp[s] == 0:
                continue
            for k in range(1, min(freq + 1, (r - s) // num + 1)):
                if s + k * num <= r:
                    dp[s + k * num] = (dp[s + k * num] + dp[s]) % MOD

    return sum(dp[l:r+1]) % MOD
