def canReachAll(nums):
    max_num = max(nums)
    if max_num == 1:
        return len(nums) == 1

    # Precompute smallest prime factor (SPF) using a sieve
    spf = list(range(max_num + 1))
    for i in range(2, int(max_num**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, max_num + 1, i):
                if spf[j] == j:
                    spf[j] = i

    parent = list(range(max_num + 1))
    def find(i):
        if parent[i] == i:
            return i
        parent[i] = find(parent[i])
        return parent[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parent[root_i] = root_j

    # For each number, union its prime factors
    for x in nums:
        temp = x
        while temp > 1:
            p = spf[temp]
            union(x, p)
            while temp % p == 0:
                temp //= p

    # Check if all numbers > 1 belong to the same component
    root = -1
    for x in nums:
        if x > 1:
            if root == -1:
                root = find(x)
            elif find(x) != root:
                return False
    return True
