                root = self.p[root]
            while x != root:
                nxt = self.p[x]
                self.p[x] = root
                x = nxt
            return root

        def union(self, x, y):
            px = self.find(x)
            py = self.find(y)
            if px == py:
                return
            if self.rank[px] < self.rank[py]:
                self.p[px] = py
            elif self.rank[px] > self.rank[py]:
                self.p[py] = px
            else:
                self.p[py] = px
                self.rank[px] += 1

    uf = UnionFind(n)
    for indices in primes_to_indices.values():
        if len(indices) < 2:
