def canTraverseAllPairs(nums):
    if len(nums) == 1:
        return True
    if 1 in nums:
        return False

    def get_prime_factors(n):
        factors = set()
        d = 2
        while d * d <= n:
            while n % d == 0:
                factors.add(d)
                n //= d
            d += 1
        if n > 1:
            factors.add(n)
        return factors

    parent = {}

    def find(x):
        if x not in parent:
            parent[x] = x
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    for num in nums:
        factors = get_prime_factors(num)
        first = True
        for p in factors:
            if first:
                union(num, p)
                first = False
            else:
                union(p, next(iter(factors)))

    roots = set()
    for num in nums:
        roots.add(find(num))

    return len(roots) == 1
