def minGroupsForValidAssignment(nums):
    from collections import Counter
    freq = Counter(nums)
    min_freq = min(freq.values())

    for group_size in range(min_freq, 0, -1):
        valid = True
        total_groups = 0
        for count in freq.values():
            q, r = divmod(count, group_size)
            if r == 0:
                total_groups += q
            elif q >= 1 and r <= group_size:
                total_groups += q + 1
            else:
                valid = False
                break
        if valid:
            return total_groups
    return len(nums)
