    LAND = []
    for row in grid:
        mask = 0
        for j, ch in enumerate(row):
            if ch == '.':
                mask |= (1 << j)
        LAND.append(mask)

    # Initial valid positions are all land cells
    m = LAND[:]

    for move in T:
        if move == 'L':
            m = [(x >> 1) & land for x, land in zip(m, LAND)]
        elif move == 'R':
            m = [(x << 1) & land for x, land in zip(m, LAND)]
        elif move == 'U':
            m = [(m[i+1] & LAND[i]) if i < H-1 else 0 for i in range(H)]
        elif move == 'D':
            m = [(m[i-1] & LAND[i]) if i > 0 else 0 for i in range(H)]

    ans = sum(bin(x).count('1') for x in m)
