def min_operations_to_equal(s1: str, s2: str, s3: str) -> int:
    # Find length of longest common prefix
    min_len = min(len(s1), len(s2), len(s3))
    lcp_len = 0
    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            lcp_len += 1
        else:
